    public static int tZeros(emon.Port.Buf b, int n) {
        // The caller's part of `cc-decode`'s contract: `n` zero bytes to paint on.
        int i = 0;
        while (i < n) {
            emon.Port.bufPush(b, 0);
            i += 1;
        }
        return 0;
    }
    public static int tStrip(int emonT, byte[] t, int k, int flags, emon.Port.Buf out, String msg) {
        // Decode the one strip of a 48 x 36 bilevel fixture; the status of the decoder.
        emon.Port.Cells r = emon.Port.newCells();
        emon.Port.Cells ws = emon.Port.newCells();
        int s = Tiffcheck.tcCheck(t, 0, 1, r);
        emon.Testport.assertEq(s, 0, msg);
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trNchunks()), 1, msg);
        int off = emon.Port.cellsAt(r, emon.Port.cellsAt(r, Tiffcheck.trOffsAt()));
        int n = emon.Port.cellsAt(r, emon.Port.cellsAt(r, Tiffcheck.trLensAt()));
        tZeros(out, 216);
        return Ccitt.ccDecode(t, off, off + n, k, 48, 36, flags, out, ws);
    }
    public static int tSame(int emonT, byte[] t, int k, byte[] none, String msg) {
        // The strip of `t` decoded is the picture the uncompressed file `none` holds, bit for bit (libtiff reads a CCITT black run as 1 bits whatever the photometric: D188).
        emon.Port.Buf got = emon.Port.newBuf();
        emon.Port.Cells r = emon.Port.newCells();
        int s = Tiffcheck.tcCheck(none, 0, 1, r);
        int off = emon.Port.cellsAt(r, emon.Port.cellsAt(r, Tiffcheck.trOffsAt()));
        int i = 0;
        emon.Testport.assertEq(tStrip(emonT, t, k, 0, got, msg), 0, msg);
        emon.Testport.assertEq(s, 0, msg);
        emon.Testport.assertEq(emon.Port.bufLen(got), 216, msg);
        while (i < 216) {
            emon.Testport.assertEq(emon.Port.bufAt(got, i), emon.Port.blobU8(none, off + i), msg);
            i += 1;
        }
        return 0;
    }
    public static void testCcittDecodesTheTiffFixtures() {
        tSame(0, emon.Testport.testFile("image/tiff-bilevel-g4.tif"), -1, emon.Testport.testFile("image/tiff-bilevel-none.tif"), "Group 4");
        tSame(0, emon.Testport.testFile("image/tiff-bilevel-g3.tif"), 0, emon.Testport.testFile("image/tiff-bilevel-none.tif"), "Group 3, one-dimensional");
    }
    public static int tRawStrip(int emonT, byte[] t, int off, int k, byte[] none, String msg) {
        // A refused TIFF (validator says no) whose strip starts at `off` and runs to the end of the strips: the decoder reads
        // what the validator will not hand over: Group 3 two-dimensional, and EOLs padded with fill bits.
        emon.Port.Buf got = emon.Port.newBuf();
        emon.Port.Cells ws = emon.Port.newCells();
        emon.Port.Cells r = emon.Port.newCells();
        int s = Tiffcheck.tcCheck(none, 0, 1, r);
        int woff = emon.Port.cellsAt(r, emon.Port.cellsAt(r, Tiffcheck.trOffsAt()));
        int i = 0;
        emon.Testport.assertEq(s, 0, msg);
        tZeros(got, 216);
        emon.Testport.assertEq(Ccitt.ccDecode(t, off, emon.Port.blobLen(t), k, 48, 36, 0, got, ws), 0, msg);
        emon.Testport.assertEq(emon.Port.bufLen(got), 216, msg);
        while (i < 216) {
            emon.Testport.assertEq(emon.Port.bufAt(got, i), emon.Port.blobU8(none, woff + i), msg);
            i += 1;
        }
        return 0;
    }
    public static void testCcittReadsWhatTheValidatorRefuses() {
        tRawStrip(0, emon.Testport.testFile("image/tiff-bilevel-g3-2d.tif"), 8, 1, emon.Testport.testFile("image/tiff-bilevel-none.tif"), "Group 3, two-dimensional");
        tRawStrip(0, emon.Testport.testFile("image/tiff-bilevel-g3-fill.tif"), 8, 0, emon.Testport.testFile("image/tiff-bilevel-none.tif"), "Group 3 with fill bits before the EOLs");
    }
    public static void testExifReader() {
        // The first directory of an EXIF blob: orientation 1..8 and the two resolutions; anything else says (1, 0, 0).
        emon.Port.Cells r = emon.Port.newCells();
        Tiffcheck.tcExif(emon.Testport.hexBlob("49492a000800000004001201030001000000060000001a010500010000003e0000001b010500010000003e000000280103000100000002000000000000002c01000001000000"), 0, 70, r);
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trEo()), 6, "orientation");
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trEx()), 30000, "horizontal resolution");
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trEy()), 30000, "vertical resolution");
        Tiffcheck.tcExif(emon.Testport.hexBlob("010203040549492a000800000004001201030001000000060000001a010500010000003e0000001b010500010000003e000000280103000100000002000000000000002c01000001000000"), 5, 70, r);
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trEo()), 6, "orientation, in a blob that starts later");
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trEx()), 30000, "... and its resolution");
        Tiffcheck.tcExif(emon.Testport.hexBlob("49492a000800000004001201030001000000010000001a010500010000003e0000001b010500010000003e000000280103000100000002000000000000009600000001000000"), 0, 70, r);
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trEo()), 1, "orientation 1");
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trEx()), 15000, "150 dpi");
        Tiffcheck.tcExif(emon.Testport.hexBlob("4d4d002b00080000"), 0, 8, r);
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trEo()), 1, "BigTIFF says nothing");
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trEx()), 0, "... of the resolution");
        Tiffcheck.tcExif(emon.Testport.hexBlob("49492a00"), 0, 4, r);
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trEo()), 1, "a blob of four bytes says nothing");
        Tiffcheck.tcExif(emon.Testport.hexBlob("49492a00ffffffff0000"), 0, 10, r);
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trEo()), 1, "a directory outside the blob says nothing");
        emon.Testport.assertEq(emon.Port.cellsAt(r, Tiffcheck.trEy()), 0, "... of the resolution");
    }
